 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            comps.append([color, cells])
    return comps


def transform(grid):
    h, w = len(grid), len(grid[0])
    comps = _components(grid)
    # Objects roll right together; let the foremost objects move first each tick.
    while True:
        moved = False
        occ = {}
        for i, (_, cells) in enumerate(comps):
            for p in cells:
                occ[p] = i
        order = sorted(range(len(comps)), key=lambda i: max(c for _, c in comps[i][1]), reverse=True)
        for i in order:
            cells = comps[i][1]
            targets = [(r, c + 1) for r, c in cells]
            if any(c >= w for _, c in targets):
                continue
            if any(p in occ and occ[p] != i for p in targets):
                continue
            for p in cells:
                occ.pop(p, None)
            comps[i][1] = targets
            for p in targets:
                occ[p] = i
            moved = True
        if not moved:
            break
    out = [[0] * w for _ in range(h)]
    for color, cells in comps:
        for r, c in cells:
            out[r][c] = color
    return out
